    site_id uuid NOT NULL,
    service_id uuid NOT NULL,
    active boolean DEFAULT true NOT NULL,
    pricing_mode public."PricingMode" NOT NULL,
    fixed_rate numeric(20,8),
    markup_percent numeric(9,6),
    fixed_profit numeric(20,8),
    min_profit numeric(20,8) DEFAULT 0 NOT NULL,
    min_override integer,
    max_override integer,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    display_name character varying(240),
    display_description text,
    CONSTRAINT site_service_rules_check CHECK (((min_override IS NULL) OR (max_override IS NULL) OR (min_override <= max_override)))
);


ALTER TABLE public.site_service_rules OWNER TO smm;

