    site_number bigint DEFAULT nextval('public.sites_site_number_seq'::regclass) NOT NULL,
    parent_site_id uuid,
    owner_user_id uuid,
    name character varying(160) NOT NULL,
    slug character varying(80) NOT NULL,
    status public."SiteStatus" DEFAULT 'PENDING'::public."SiteStatus" NOT NULL,
    depth integer NOT NULL,
    deleted_at timestamp(3) with time zone,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT sites_depth_check CHECK ((depth >= 0)),
    CONSTRAINT sites_no_self_parent CHECK (((parent_site_id IS NULL) OR (parent_site_id <> id)))
);


ALTER TABLE public.sites OWNER TO smm;

