--
-- Name: wallet_transactions; Type: TABLE; Schema: public; Owner: smm
--

CREATE TABLE public.wallet_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    wallet_id uuid NOT NULL,
    user_id uuid NOT NULL,
    type public."TransactionType" NOT NULL,
    amount numeric(20,8) NOT NULL,
    balance_before numeric(20,8) NOT NULL,
    balance_after numeric(20,8) NOT NULL,
    reference_id character varying(128),
    idempotency_key character varying(128) NOT NULL,
    description character varying(500),
    metadata jsonb,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    site_id uuid NOT NULL,
    CONSTRAINT wallet_transactions_balance_equation_check CHECK ((balance_after = (balance_before + amount))),
    CONSTRAINT wallet_transactions_balances_nonnegative_check CHECK (((balance_before >= (0)::numeric) AND (balance_after >= (0)::numeric))),
    CONSTRAINT wallet_transactions_nonzero_amount_check CHECK ((amount <> (0)::numeric))
);


ALTER TABLE public.wallet_transactions OWNER TO smm;

